-- migrate:up

-- Private subscription tables (spec §4.1, §10, §11). They never appear in public exports.
-- Hashes are lowercase hex; see web/lib/subscriptions/crypto.ts for how each is computed.

CREATE TABLE subscriptions (
    -- Random (generated by the web), so manage tokens derived from it are not guessable.
    id                   uuid PRIMARY KEY,
    -- Normalized: trimmed and lowercased.
    email                text NOT NULL CHECK (email = lower(btrim(email)) AND length(email) BETWEEN 3 AND 254),
    locale               text NOT NULL CHECK (locale IN ('en', 'nl', 'zh')),
    -- {"sources": [...], "hazard_categories": [rasff_id...], "product_categories": [rasff_id...],
    --  "origin_countries": [iso2...]}; an empty array means no restriction (spec §10.1).
    filters              jsonb NOT NULL,
    include_unclassified boolean NOT NULL DEFAULT true,
    instant_sources      text[] NOT NULL DEFAULT '{}'
        CHECK (instant_sources <@ ARRAY['rasff', 'nvwa', 'openfda']),
    status               text NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'active', 'unsubscribed')),
    -- SHA-256 of the emailed confirm token; cleared once confirmed.
    confirm_token_hash   text UNIQUE,
    confirm_expires_at   timestamptz,
    -- SHA-256 of the manage token (HMAC of the id, so the mailer can rebuild links).
    manage_token_hash    text NOT NULL UNIQUE,
    consent_at           timestamptz NOT NULL,
    consent_text_version text NOT NULL,
    -- HMAC of the client IP with a server-side pepper; the IP itself is never stored.
    consent_ip_hash      text,
    created_at           timestamptz NOT NULL DEFAULT now(),
    confirmed_at         timestamptz,
    unsubscribed_at      timestamptz,
    CHECK (jsonb_typeof(filters) = 'object'),
    -- Chinese subscriptions cover NVWA only (spec §10.1).
    CHECK (locale <> 'zh' OR filters -> 'sources' = '["nvwa"]'::jsonb),
    CHECK ((status = 'unsubscribed') = (unsubscribed_at IS NOT NULL)),
    CHECK ((status = 'active') <= (confirmed_at IS NOT NULL)),
    CHECK ((confirm_token_hash IS NULL) = (confirm_expires_at IS NULL))
);

-- One live Subscription per address; an unsubscribed address may subscribe again.
CREATE UNIQUE INDEX subscriptions_email_live_idx ON subscriptions (email)
    WHERE status <> 'unsubscribed';
CREATE INDEX subscriptions_status_idx ON subscriptions (status, created_at);

-- Do-not-send list after "delete my data" (spec §11.1 #5): HMAC of the normalized email.
CREATE TABLE email_suppressions (
    email_hash text PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT now()
);

-- Every email sent; kept 12 months (spec §11.1 #6). Rows go with their Subscription.
CREATE TABLE email_deliveries (
    id                  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    subscription_id     uuid NOT NULL REFERENCES subscriptions (id) ON DELETE CASCADE,
    kind                text NOT NULL CHECK (kind IN ('confirm', 'digest', 'instant')),
    notification_ids    bigint[] NOT NULL DEFAULT '{}',
    sent_at             timestamptz NOT NULL DEFAULT now(),
    provider_message_id text
);

CREATE INDEX email_deliveries_subscription_idx ON email_deliveries (subscription_id, kind, sent_at DESC);
CREATE INDEX email_deliveries_sent_idx ON email_deliveries (sent_at);

-- The website sends confirmation emails but may not write email_deliveries (spec §11.2).
-- This function is its only way in: one 'confirm' row for a pending Subscription.
CREATE FUNCTION record_confirm_delivery(p_subscription_id uuid, p_provider_message_id text)
RETURNS bigint
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
    INSERT INTO public.email_deliveries (subscription_id, kind, provider_message_id)
    SELECT s.id, 'confirm', p_provider_message_id
    FROM public.subscriptions s
    WHERE s.id = p_subscription_id AND s.status = 'pending'
    RETURNING id
$$;

-- Privileges (spec §11.2). ofa_pipeline gets every new table through default privileges;
-- these are private, so take that back.
REVOKE ALL ON subscriptions, email_suppressions, email_deliveries FROM ofa_pipeline;
REVOKE ALL ON SEQUENCE email_deliveries_id_seq FROM ofa_pipeline;
REVOKE ALL ON FUNCTION record_confirm_delivery(uuid, text) FROM PUBLIC;

GRANT SELECT, INSERT, UPDATE, DELETE ON subscriptions, email_suppressions TO ofa_web;
GRANT SELECT ON email_deliveries TO ofa_web;
GRANT EXECUTE ON FUNCTION record_confirm_delivery(uuid, text) TO ofa_web;

-- The mailer (Digest, Instant email) reads Subscriptions and public tables and records
-- what it sent. Later migrations that add public tables grant SELECT to it as needed.
GRANT SELECT ON subscriptions, email_suppressions TO ofa_mailer;
GRANT SELECT, INSERT ON email_deliveries TO ofa_mailer;
GRANT SELECT ON sources, notifications, notification_versions, countries, hazard_categories,
    product_categories, notification_hazards, notification_product_categories,
    notification_countries, measures TO ofa_mailer;

-- migrate:down
REVOKE SELECT ON sources, notifications, notification_versions, countries, hazard_categories,
    product_categories, notification_hazards, notification_product_categories,
    notification_countries, measures FROM ofa_mailer;
DROP FUNCTION record_confirm_delivery(uuid, text);
DROP TABLE email_deliveries;
DROP TABLE email_suppressions;
DROP TABLE subscriptions;
